contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dummy) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(dummy == dummy);
        require(address(this).balance >= 0);

        uint256 prevValue = c.value(); if (__ESBMC_reverted()) return;
        uint256 prevRemaining = c.totalRemaining(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.getTokens(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 newValue = c.value(); if (__ESBMC_reverted()) return;

        assert(
            reverted ||
            (prevValue > prevRemaining && newValue == prevValue) ||
            (prevValue <= prevRemaining && newValue == (prevValue / 100000) * 99999)
        );
    }

    receive() external payable {}
}

